import {clone,esc,fmt,timeLabel,addCell,connect,removePart,describeConnection,History,samePhysics,actualTestName} from './studio-state.mjs';
import {renderCanvas,thumbnail,heroBattery,palette,wireGeometry} from './studio-canvas.mjs';
import {chartSvg,chartFields,pointValues,nearestIndex,probeSvg} from './studio-charts.mjs';

const app=document.querySelector('#app'), dialog=document.querySelector('#dialog');
const S={token:null,catalog:null,doc:null,graph:null,settings:null,view:'build',mode:'assembly',selected:null,tool:'select',pending:null,
  ai:false,messages:[],chatBusy:false,chatError:null,proposal:null,history:new History(),dirty:false,saving:false,saveError:false,
  test:null,index:0,metric:'current',layer:'temperature',hidden:new Set(),running:false,testError:null,onboarding:false,comparison:null};
let saveTimer,savePromise=null,toastTimer,templateChoice='parallel',chartPinned=false,chatDraft='';
const icons={
 battery:'<rect x="4" y="5" width="15" height="14" rx="3"/><path d="M19 10h2v4h-2M8 9v6m4-6v6m4-6v6"/>',
 logo:'<path d="M4 5v14h7V7h5v7h4M2 5h4M9 7h4M18 14h4"/>',
 spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/><path d="M20 2v4m-2-2h4"/>',
 plus:'<path d="M12 5v14M5 12h14"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',
 chevron:'<path d="m9 5 7 7-7 7"/>',back:'<path d="m10 5-7 7 7 7M3 12h17"/>',
 play:'<path d="m8 4 12 8-12 8Z"/>',undo:'<path d="M8 5 3 10l5 5M3 10h10a7 7 0 0 1 7 7"/>',redo:'<path d="m16 5 5 5-5 5M21 10H11a7 7 0 0 0-7 7"/>',
 trash:'<path d="M4 7h16M9 7V4h6v3M6 7l1 14h10l1-14M10 11v6m4-6v6"/>',wire:'<circle cx="5" cy="6" r="2"/><circle cx="19" cy="18" r="2"/><path d="M7 6h5v12h5"/>',
 pointer:'<path d="m5 3 3 17 4-6 7-1Z"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3v2M12 17h.01"/>',
 chart:'<path d="M4 3v17h17M7 15l4-5 4 3 5-8"/>',check:'<path d="m5 12 4 4L20 5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',
 folder:'<path d="M3 7V5h7l2 3h9v12H3Z"/>',copy:'<rect x="8" y="8" width="12" height="13" rx="2"/><path d="M16 8V3H3v13h5"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',thermometer:'<path d="M10 14V5a2 2 0 0 1 4 0v9a5 5 0 1 1-4 0ZM12 8v10"/>',
 compare:'<path d="M8 3v18M16 3v18M4 7h8m0 10h8"/>',load:'<path d="m13 2-8 12h6l-1 8 9-13h-6Z"/>',
 edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-5-5L4 14Z"/>',send:'<path d="m4 11 8-8 8 8M12 3v18"/>',
 series:'<rect x="3" y="7" width="5" height="10" rx="1"/><rect x="16" y="7" width="5" height="10" rx="1"/><path d="M8 12h8M1 12h2m18 0h2"/>',
 parallel:'<rect x="7" y="3" width="10" height="5" rx="1"/><rect x="7" y="16" width="10" height="5" rx="1"/><path d="M7 5H3v14h4m10-14h4v14h-4M1 12h2m18 0h2"/>',
 grid:'<rect x="3" y="3" width="6" height="6" rx="1"/><rect x="15" y="3" width="6" height="6" rx="1"/><rect x="3" y="15" width="6" height="6" rx="1"/><rect x="15" y="15" width="6" height="6" rx="1"/>'};
const icon=(name,cls='')=>`<svg viewBox="0 0 24 24" aria-hidden="true" class="icon ${cls}">${icons[name]||icons.info}</svg>`;
const btn=(action,label,ico,cls='',disabled=false,extra='')=>`<button type="button" data-act="${action}" class="${cls}" ${disabled?'disabled':''} ${extra}>${ico?icon(ico):''}${label}</button>`;
const iconBtn=(action,label,ico,disabled=false)=>btn(action,'',ico,'icon-button quiet',disabled,`aria-label="${esc(label)}" title="${esc(label)}"`);
function notify(message,error=false){clearTimeout(toastTimer);document.querySelector('#notifications').innerHTML=`<div class="toast ${error?'error':''}">${esc(message)}</div>`;toastTimer=setTimeout(()=>document.querySelector('#notifications').replaceChildren(),error?7000:3500);}
async function api(operation,args={}){
  const r=await fetch('/api/studio',{method:'POST',headers:{'Content-Type':'application/json','X-Voltforge-Token':S.token},body:JSON.stringify({operation,arguments:args})});
  let value;try{value=await r.json();}catch{throw new Error('The workspace connection was interrupted. Your last saved design is safe.');}
  if(!r.ok||value.status!=='ok')throw new Error(value.error?.message||'This action could not finish. Try again.');return value.result;
}
function dirty(){S.dirty=true;S.saveError=false;clearTimeout(saveTimer);saveTimer=setTimeout(()=>persist().catch(e=>notify(e.message,true)),700);updateSaveStatus();}
function updateSaveStatus(){const el=document.querySelector('#save-status');if(el)el.textContent=S.saveError?'Save failed':S.saving?'Saving…':S.dirty?'Unsaved changes':'Saved';}
async function persist(){
  clearTimeout(saveTimer);
  if(savePromise){await savePromise;if(S.dirty)return persist();return;}
  if(!S.doc||!S.dirty)return;
  const designId=S.doc.id,graph=clone(S.graph),settings=clone(S.settings),version=S.doc.version;
  S.dirty=false;S.saving=true;updateSaveStatus();
  savePromise=api('save',{design_id:designId,version,graph,settings}).then(doc=>{
    if(S.doc?.id!==designId)return;
    S.doc=doc;S.saveError=false;
    if(S.test)S.test.current=doc.history.find(t=>t.id===S.test.id)?.current??false;
    const check=document.querySelector('#circuit-check');if(check)check.outerHTML=readinessLabel();
  }).catch(e=>{S.dirty=true;S.saveError=true;throw e;}).finally(()=>{S.saving=false;savePromise=null;updateSaveStatus();});
  await savePromise;
}
function snapshot(){return {graph:clone(S.graph),settings:clone(S.settings)};}
function mutate(fn,{renderNow=true}={}){S.history.push(snapshot());fn();dirty();if(renderNow)render();}
function readinessLabel(){const ok=S.doc?.readiness?.ready&&!S.dirty;return `<span id="circuit-check" class="circuit-check ${ok?'':'incomplete'}"><span class="status-dot"></span>${S.dirty?'Checking connections…':ok?'Ready to test':'Finish your connections'}</span>`;}
function header(){return `<header class="topbar"><button class="brand" data-act="home" aria-label="VOLT-FORGE home"><span class="brand-mark">${icon('logo')}</span>VOLT-FORGE</button>${S.doc?`<span class="top-divider"></span><button class="project-name" data-act="rename" title="Rename design">${esc(S.graph.name)}</button><span id="save-status" class="save-status">${S.saving?'Saving…':S.dirty?'Unsaved changes':'Saved'}</span><nav aria-label="Workspace steps" class="workspace-nav">${['build','test','results'].map(v=>btn('view:'+v,v[0].toUpperCase()+v.slice(1),null,S.view===v?'active':'')).join('')}</nav>`:''}<div class="top-actions">${btn('designs','My designs','folder','quiet designs-button')}${btn('help','Help','help','quiet help-button')}${btn('ai','AI copilot','spark','copilot-button '+(S.ai?'active':''),false,`aria-expanded="${S.ai}"`)}</div></header>`;}
function home(){const designs=S.catalog?.designs||[];return `<main id="main" class="home"><section class="home-top"><div class="home-copy"><h1>Build a battery.<br>Understand what changes.</h1><p>Connect cells, test your design and see how each decision changes its behaviour.</p><div class="home-buttons">${btn('example','Open four-cell example','play','primary')}${btn('new','New design','plus')}</div></div>${heroBattery()}</section><form id="home-chat" class="home-ai">${icon('spark')}<label for="home-prompt" class="sr-only">Describe a battery design</label><input id="home-prompt" name="prompt" placeholder="Or describe a design to the AI copilot…" autocomplete="off" maxlength="4000"><button class="primary" type="submit" aria-label="Ask AI copilot">${icon('arrow')}</button></form>${designs.length?`<section class="recent-designs"><div class="section-heading"><h2>Continue a design</h2>${designs.length>3?btn('designs','View all',null,'text-button'):''}</div><div class="design-list">${designs.slice(0,3).map(designRow).join('')}</div></section>`:''}<p class="home-foot">Your designs are saved on this computer.</p></main>`;}
function designRow(d){return `<button class="design-item" data-act="open:${esc(d.id)}"><span class="design-glyph">${icon('battery')}</span><span><span class="design-title">${esc(d.name)}</span><span class="design-meta">${d.cells} ${d.cells===1?'cell':'cells'}${d.tests?' · '+d.tests+' saved '+(d.tests===1?'test':'tests'):''}</span></span>${icon('chevron','chevron')}</button>`;}
function build(){const g=S.graph,first=!g.cells.length;return `<main id="main" class="build-area"><div class="canvas-heading"><div><h1>${esc(g.name)}</h1><p>${g.cells.length?`${g.cells.length} ${g.cells.length===1?'cell':'cells'} · your editable battery design`:'An empty canvas for your battery'}</p></div><div class="canvas-heading-actions"><div class="segment" aria-label="Design view">${btn('mode:assembly','Assembly',null,S.mode==='assembly'?'active':'')}${btn('mode:circuit','Circuit',null,S.mode==='circuit'?'active':'')}</div>${btn('view:test','Test this design','play','primary',S.running)}</div></div><section class="canvas-stage" aria-label="Battery design canvas"><div class="canvas-topline"><div class="tools">${btn('library','Add cell','plus','add-cell-button',g.cells.length>=16)}<span class="tool-divider"></span>${btn('tool:select','<span class="tool-name">Select</span>','pointer',S.tool==='select'?'active':'',false,'title="Select and move a cell"')}${btn('tool:connect','<span class="tool-name">Connect</span>','wire',S.tool==='connect'?'active':'',!g.cells.length,'title="Connect two terminals"')}<span class="tool-divider"></span>${iconBtn('undo','Undo','undo',!S.history.undo.length)}${iconBtn('redo','Redo','redo',!S.history.redo.length)}${iconBtn('delete','Delete selected component','trash',!S.selected||S.selected.includes(':'))}</div>${iconBtn('help','Canvas guide','help')}</div><div class="canvas-model" id="canvas-model">${renderCanvas(g,{mode:S.mode,selected:S.selected,tool:S.tool,pending:S.pending})}${first?`<div class="blank-canvas">${icon('battery')}<h2>Start with a cell</h2><p>Add cells, then connect their positive and negative terminals.</p>${btn('library','Add your first cell','plus','primary')}</div>`:''}${S.onboarding&&g.cells.length?`<div class="floating-helper"><strong>Try changing one cell.</strong>Click a cell to change its starting charge. Use Connect to wire any two terminals.${btn('dismiss-guide','Got it',null,'text-button')}</div>`:''}</div><div class="canvas-bottomline"><span class="canvas-hint">${icon(S.tool==='connect'?'wire':'pointer')}${S.tool==='connect'?(S.pending?'Choose the second terminal to finish the connection.':'Click a positive or negative terminal to start a connection.'):'Select a cell to edit it. Drag to arrange your design.'}</span>${readinessLabel()}</div></section></main>`;}
function testSetup(){const s=S.settings,p=s.profile[0],duration=s.profile.at(-1).end_s;return `<main id="main" class="page-wrap"><div class="page-intro"><h1>Put your design to the test</h1><p>Choose the load, how long it runs and the room temperature.</p></div><div class="test-layout"><form id="test-form" class="test-form"><h2>Test conditions</h2><div class="field"><label for="test-direction">What should the battery do?</label><select id="test-direction" name="direction"><option value="discharge" ${p.current_A>=0?'selected':''}>Power something · discharge</option><option value="charge" ${p.current_A<0?'selected':''}>Recharge the cells</option><option value="rest" ${p.current_A===0?'selected':''}>Rest with no external load</option></select></div><div class="field-row"><div class="field"><label for="test-current">Battery current</label><div class="input-unit"><input id="test-current" name="current" type="number" min="0" max="200" step="0.1" value="${Math.abs(p.current_A)}" required><span>A</span></div><p>The total current at the battery output.</p></div><div class="field"><label for="test-duration">Test duration</label><div class="input-unit"><input id="test-duration" name="duration" type="number" min="0.02" max="1440" step="any" value="${duration/60}" required><span>min</span></div><p>Choose the length of your experiment.</p></div></div><div class="field"><label for="test-ambient">Room temperature</label><div class="input-unit"><input id="test-ambient" name="ambient" type="number" min="22" max="28" step="0.1" value="${s.ambient_C}" required><span>°C</span></div></div><details><summary>Change the load during the test</summary><div><p class="helper">Add intervals for changing demand, charging or rest. Negative current recharges; zero current rests.</p><div id="load-intervals">${s.profile.map((r,i)=>intervalRow(r,i)).join('')}</div>${btn('add-interval','Add interval','plus','text-button')}<p class="helper">When intervals are present, their durations and currents set the test.</p></div></details><details class="test-targets"><summary>Set targets to check</summary><div><p class="helper">Use your design requirements. An empty field leaves that check off.</p><div class="field-row"><div class="field"><label for="target-temperature">Maximum cell temperature</label><div class="input-unit"><input id="target-temperature" name="limit_temperature" type="number" step="any" value="${s.limits.temperature_C??''}" placeholder="Optional"><span>°C</span></div></div><div class="field"><label for="target-current">Maximum cell current</label><div class="input-unit"><input id="target-current" name="limit_current" type="number" min="0" step="any" value="${s.limits.current_A??''}" placeholder="Optional"><span>A</span></div></div></div><div class="field-row"><div class="field"><label for="target-voltage">Minimum battery voltage</label><div class="input-unit"><input id="target-voltage" name="limit_voltage" type="number" min="0" step="any" value="${s.limits.min_voltage_V??''}" placeholder="Optional"><span>V</span></div></div><div class="field"><label for="target-imbalance">Maximum current difference</label><div class="input-unit"><input id="target-imbalance" name="limit_imbalance" type="number" min="0" step="any" value="${s.limits.imbalance_pct??''}" placeholder="Optional"><span>%</span></div></div></div><p class="helper">The percentage is the largest cell-current spread divided by the mean current. It applies to parallel branches.</p></div></details><details><summary>Solver and heat transfer</summary><div><div class="field-row"><div class="field"><label for="test-step">Time step <small>(s)</small></label><input id="test-step" name="step" type="number" min="0.01" max="10" step="any" value="${s.dt_s}" required><p>Smaller steps resolve fast electrical changes.</p></div><div class="field"><label for="heat-capacity">Cell heat capacity <small>(J/°C)</small></label><input id="heat-capacity" name="heat_capacity" type="number" min="1" max="10000" step="any" value="${S.graph.thermal.heat_capacity_J_K}" required><p>Energy needed to warm one cell by 1 °C. Editing sets all cells.</p></div></div><div class="field"><label for="cooling-conductance">Cooling to the room <small>(W/°C per cell)</small></label><input id="cooling-conductance" name="cooling" type="number" min="0" max="100" step="any" value="${S.graph.thermal.ambient_conductance_W_K}" required><p>Heat removed per degree above room temperature. Set this from your fixture or measurements. Editing sets all cells.</p></div>${btn('thermal-contacts','Edit cell-to-cell heat contacts','edit','text-button')}</div></details>${S.testError?`<div class="error-inline" role="alert">${esc(S.testError)}</div>`:''}<div class="test-action">${S.running?`<div class="running-state"><div class="loading-mark"></div>Calculating your circuit…</div>`:'<span class="helper">Electrical + thermal simulation</span>'}<button type="submit" class="primary" ${S.running?'disabled':''}>${icon('play')}${S.running?'Testing…':'Run test'}</button></div></form><aside class="test-summary"><h2>${esc(S.graph.name)}</h2><div class="battery-preview">${renderCanvas(S.graph,{mode:'assembly',prefix:'test'})}</div><dl><div><dt>Cells</dt><dd>${S.graph.cells.length}</dd></div><div><dt>Starting charge</dt><dd>${startingRange('charge_pct','%')}</dd></div><div><dt>Starting temperature</dt><dd>${startingRange('temperature_C',' °C')}</dd></div><div><dt>Connections</dt><dd>${S.graph.connections.length}</dd></div></dl>${btn('view:build','Edit the design','back','text-button')}${!S.doc.readiness.ready?`<div class="info-inline">${esc(S.doc.readiness.message)}</div>`:''}</aside></div></main>`;}
function intervalRow(p,i){return `<div class="interval-row" data-interval="${i}"><div><label for="interval-duration-${i}">Interval ${i+1} · minutes</label><input id="interval-duration-${i}" class="interval-duration" type="number" min="0.001" step="any" value="${(p.end_s-p.start_s)/60}"></div><div><label for="interval-current-${i}">Current (A)</label><input id="interval-current-${i}" class="interval-current" type="number" min="-200" max="200" step="any" value="${p.current_A}"></div>${iconBtn('remove-interval:'+i,'Remove interval '+(i+1),'trash',S.settings.profile.length===1)}</div>`;}
function startingRange(key,unit){const v=S.graph.cells.map(c=>c[key]);if(!v.length)return '—';return (Math.min(...v)===Math.max(...v)?fmt(v[0],0):`${fmt(Math.min(...v),0)}–${fmt(Math.max(...v),0)}`)+unit;}
function results(){if(!S.test)return `<main id="main" class="page-wrap"><div class="empty-results">${icon('chart')}<h1>See what your design does</h1><p>Run a test to explore each cell’s current, temperature, voltage and charge.</p>${btn('view:test','Set up a test','play','primary')}${S.doc.history.length?`<div class="field">${historySelect()}</div>`:''}</div></main>`;
 const t=S.test,m=t.summary.metrics,charging=t.settings.profile.every(p=>p.current_A<=0)&&t.settings.profile.some(p=>p.current_A<0),field=chartFields[S.metric],names=Object.fromEntries(t.graph.cells.map(c=>[c.id,c.name]));
 return `<main id="main" class="page-wrap"><div class="results-heading"><div><h1>Your test results</h1><p>${esc(t.name)} · ${esc(t.design_name)} <span class="status-pill ${t.current?'estimate':'old'}">${t.current?'Simulation': 'Earlier design version'}</span></p></div><div class="result-actions">${historySelect()}${btn('export','Export','download','',false,'title="Download report, data and reproducible model"')}</div></div>${t.stop?`<div class="info-inline">The test stopped at ${timeLabel(m.duration_s)}. ${esc(t.stop.message)}</div>`:''}${!t.current?`<div class="info-inline">The design, test settings or model version has changed since this result. ${btn('view:test','Test the current design',null,'text-button')}</div>`:''}<div class="results-metrics"><div class="result-metric"><span>Warmest cell</span><strong>${fmt(m.peak_temperature_C)} <small>°C</small></strong><p>${esc(names[m.warmest_cell])} · ${timeLabel(m.warmest_time_s)}</p></div><div class="result-metric"><span>Largest cell current</span><strong>${fmt(m.peak_cell_current_A,2)} <small>A</small></strong><p>${esc(names[m.busiest_cell])}</p></div><div class="result-metric"><span>${charging?'Energy received':'Energy delivered'}</span><strong>${fmt(charging?m.received_energy_Wh:m.delivered_energy_Wh,2)} <small>Wh</small></strong><p>Over ${timeLabel(m.duration_s)}</p></div></div><section class="result-body"><div class="chart-toolbar"><h2>${field.title}</h2><div class="segment" aria-label="Result to explore">${['current','temperature','voltage','charge'].map(k=>btn('metric:'+k,k[0].toUpperCase()+k.slice(1),null,S.metric===k?'active':'')).join('')}</div></div><div class="chart-area" id="chart-area">${chartSvg(t,S.metric,S.index,S.hidden)}<div id="chart-tooltip" class="chart-tooltip"></div></div><div class="chart-legend">${t.graph.cells.map((c,i)=>btn('legend:'+i,`<span class="series-dot series-${i%4}"></span>${esc(c.name)}`,null,S.hidden.has(i)?'muted-series':'',false,`aria-pressed="${!S.hidden.has(i)}"`)).join('')}</div><div class="chart-time-control"><label for="result-time" class="sr-only">Inspect test time</label><span id="time-readout" class="time-readout">${timeLabel(t.rows[S.index].time_s)}</span><input id="result-time" type="range" min="0" max="${t.rows.length-1}" value="${S.index}" step="1" aria-valuetext="${timeLabel(t.rows[S.index].time_s)}"><span>${timeLabel(m.duration_s)}</span></div><div class="insights">${icon('spark')}<div><h3>What this test shows</h3>${t.summary.insights.slice(0,2).map(i=>`<p>${esc(i)}</p>`).join('')}${btn('ask-results','Explore these results with AI','arrow','text-button')}</div></div></section><div class="results-next">${btn('whatif','Try a what-if','load')}${btn('compare','Compare designs','compare')}${btn('show-assembly','See values on the battery','battery')}</div>${S.showAssembly?`<div class="results-assembly" id="results-assembly">${renderCanvas(t.graph,{mode:S.mode,selected:S.selected,layer:S.metric,row:t.rows[S.index],prefix:'results'})}</div>`:''}${targetChecks(t)}<div class="details-link">${btn('model','About this model',null,'text-button')}${btn('verification','Calculation checks',null,'text-button')}</div></main>`;}
function historySelect(){return `<label class="sr-only" for="test-history">Saved tests</label><select id="test-history" class="history-select" aria-label="Saved tests"><option value="">Choose a saved test</option>${S.doc.history.map(t=>`<option value="${esc(t.id)}" ${S.test?.id===t.id?'selected':''}>${esc(t.name)}${t.current?'':' · earlier version'}</option>`).join('')}</select>`;}
function targetChecks(t){const labels={temperature_C:'Cell temperature',current_A:'Cell current',min_voltage_V:'Battery voltage',imbalance_pct:'Current difference'},units={temperature_C:'°C',current_A:'A',min_voltage_V:'V',imbalance_pct:'%'};return t.summary.checks.length?`<details><summary>Your design targets</summary>${t.summary.checks.map(c=>`<div class="check-row"><span>${labels[c.metric]}<p>${c.metric==='min_voltage_V'?'Minimum':'Maximum'} ${fmt(c.target)} ${units[c.metric]}</p></span><span class="check-value ${c.status==='within_target'?'within':'exceeded'}">${c.status==='not_applicable'?'Not applicable':`${fmt(c.value)} ${units[c.metric]} · ${c.status==='exceeded'?'Target exceeded':'Within target'}`}</span></div>`).join('')}</details>`:'';}
function whatif(){return `<main id="main" class="page-wrap"><div class="page-intro">${btn('view:results','Back to results','back','text-button')}<h1>Change one thing. See the difference.</h1><p>Each what-if creates a separate design and runs a real test. Your original stays available for comparison.</p></div><div class="whatif-options"><div class="whatif-option">${icon('load')}<div><h2>Ask for more power</h2><p>Increase the battery current by 50%. See which cell works hardest and how its temperature changes.</p></div>${btn('scenario:load','Try 1.5× load','arrow','',S.running)}</div><div class="whatif-option">${icon('wire')}<div><h2>Make one connection worse</h2><p>Add 3 mΩ to the first connection. Explore how a worn contact changes the paths that current takes.</p></div>${btn('scenario:connection','Try connection wear','arrow','',S.running||!S.graph.connections.length)}</div><div class="whatif-option">${icon('battery')}<div><h2>Start one cell less charged</h2><p>Lower the first cell’s starting charge by 10 percentage points. See how it interacts with the others.</p></div>${btn('scenario:charge','Try uneven charge','arrow','',S.running||!S.graph.cells.length)}</div></div>${S.running?'<div class="field running-state"><div class="loading-mark"></div>Testing the changed design…</div>':''}<div class="details-link">${btn('view:test','Choose your own test conditions','edit','text-button')}${btn('ai','Ask the AI for another experiment','spark','text-button')}</div></main>`;}
function comparison(){const all=S.allTests||[];return `<main id="main" class="page-wrap"><div class="page-intro">${btn('view:results','Back to results','back','text-button')}<h1>Compare two tests</h1><p>Look at the design changes and their consequences under the same conditions.</p></div>${all.length<2?`<p>Run a second design or try a what-if to create an alternative.</p>${btn('whatif','Try a what-if','load','primary')}`:`<form id="compare-form" class="comparison-controls"><div><label for="compare-left">First design and test</label><select id="compare-left" name="left">${all.map(t=>`<option value="${t.id}" ${S.compareLeft===t.id?'selected':''}>${esc(actualTestName(t))}</option>`).join('')}</select></div><div><label for="compare-right">Second design and test</label><select id="compare-right" name="right">${all.map(t=>`<option value="${t.id}" ${S.compareRight===t.id?'selected':''}>${esc(actualTestName(t))}</option>`).join('')}</select></div><button type="submit" class="primary">Compare</button></form>`}${S.comparison?comparisonResults(S.comparison):''}</main>`;}
function comparisonResults(c){const [a,b]=c.tests,am=a.summary.metrics,bm=b.summary.metrics;const fields=[['Warmest cell','peak_temperature_C','°C'],['Largest cell current','peak_cell_current_A','A'],['Energy delivered','delivered_energy_Wh','Wh'],['Lowest battery voltage','minimum_voltage_V','V'],['Temperature difference','maximum_temperature_spread_C','°C'],['Test duration','duration_s','s']];return `<div class="compare-notice ${!c.identical_test_conditions||!c.comparable_duration?'info-inline':''}">${esc(c.note)}${!c.comparable_duration?' The tests stopped at different times, so energy totals cover different durations.':''}</div><div class="compare-designs">${c.tests.map((t,i)=>`<div><h3>${esc(t.design_name)}</h3>${renderCanvas(t.graph,{prefix:'compare'+i})}</div>`).join('')}</div><div class="field"><table class="compare-table"><thead><tr><th>Result</th><th>First test</th><th>Second test</th><th>Difference</th></tr></thead><tbody>${fields.map(([label,key,unit])=>`<tr><td>${label}</td><td>${fmt(am[key],2)} <small>${unit}</small></td><td>${fmt(bm[key],2)} <small>${unit}</small></td><td>${c.deltas[key]>0?'+':''}${fmt(c.deltas[key],2)} <small>${unit}</small></td></tr>`).join('')}</tbody></table></div><p class="helper">A difference is not automatically an improvement. Use your requirements to judge the trade-off.</p>`;}
function selectedPanel(){const g=S.view==='results'&&S.test?S.test.graph:S.graph,c=g.cells.find(c=>c.id===S.selected),w=g.connections.find(w=>w.id===S.selected),terminal=S.selected?.includes(':')?S.selected:null;const title=c?'Selected cell':w?'Selected connection':'Selected terminal';let body='';
 if(c){const i=g.cells.indexOf(c),row=S.view==='results'&&S.test?S.test.rows[S.index]:null;body=`<div class="selection-card">${thumbnail(c)}<div><h2>${esc(c.name)}</h2><p>LG M50T battery cell</p><p class="sample-label">${esc(S.catalog.library.find(m=>m.key===c.model)?.name||'Measured-data cell model')}</p></div></div>${row?`<h3>At ${timeLabel(row.time_s)}</h3><div class="panel-section reading-grid"><div><span>Current</span><strong>${fmt(row.cell_current_A[i],2)} <small>A</small></strong></div><div><span>Temperature</span><strong>${fmt(row.temperature_C[i])} <small>°C</small></strong></div><div><span>Voltage</span><strong>${fmt(row.cell_voltage_V[i],3)} <small>V</small></strong></div><div><span>Charge left</span><strong>${fmt(row.charge_pct[i])}<small>%</small></strong></div></div>${btn('edit-selected','Edit this cell','edit','text-button')}`:`<div class="field"><label for="cell-charge">Starting charge</label><div class="charge-control"><input id="cell-charge-range" type="range" min="15" max="95" step="1" value="${c.charge_pct}" aria-label="Starting charge"><div class="input-unit"><input id="cell-charge" type="number" min="15" max="95" step="1" value="${c.charge_pct}" data-cell-field="charge_pct" aria-label="Starting charge percent"></div><span>%</span></div><p>How full this cell is when the test begins.</p></div><div class="field"><label for="cell-temperature">Starting temperature</label><div class="input-unit"><input id="cell-temperature" type="number" min="22" max="28" step="0.1" value="${c.temperature_C}" data-cell-field="temperature_C"><span>°C</span></div><p>The cell’s temperature at the start, which can differ from the room.</p></div><div class="field"><label for="cell-name">Cell name</label><input id="cell-name" maxlength="60" value="${esc(c.name)}" data-cell-field="name"></div><details><summary>Cell model and data</summary><p>Each sample represents a different cell measured in the same experimental campaign.</p><div class="field"><label for="cell-model">Measured sample</label><select id="cell-model" data-cell-field="model">${S.catalog.library.map(m=>`<option value="${m.key}" ${m.key===c.model?'selected':''}>${esc(m.name)}</option>`).join('')}</select></div><dl><div><dt>Measured capacity</dt><dd>${fmt(S.catalog.library.find(m=>m.key===c.model)?.capacity_Ah,2)} Ah</dd></div><div><dt>Fitted resistance</dt><dd>${fmt(S.catalog.library.find(m=>m.key===c.model)?.resistance_mohm,1)} mΩ</dd></div></dl><p>Capacity describes stored charge. Resistance describes the immediate voltage drop and heat under load.</p><p><a href="https://data.mendeley.com/datasets/zh58byr53c/2" target="_blank" rel="noopener">View the source dataset</a></p></details><details><summary>Heating and cooling</summary><p>These values describe how this cell stores heat and releases it to the room.</p><div class="field"><label for="cell-heat-capacity">Heat capacity (J/°C)</label><input id="cell-heat-capacity" type="number" min="1" max="10000" step="any" value="${S.graph.thermal.cell_parameters?.[c.id]?.heat_capacity_J_K??S.graph.thermal.heat_capacity_J_K}" data-cell-thermal="heat_capacity_J_K"><p>Energy needed to warm this cell by 1 °C.</p></div><div class="field"><label for="cell-cooling">Cooling to the room (W/°C)</label><input id="cell-cooling" type="number" min="0" max="100" step="any" value="${S.graph.thermal.cell_parameters?.[c.id]?.ambient_conductance_W_K??S.graph.thermal.ambient_conductance_W_K}" data-cell-thermal="ambient_conductance_W_K"><p>Heat released per degree above room temperature.</p></div></details><details><summary>Initial electrical relaxation</summary><p>After changing load, a cell takes time to settle. Leave this at zero for the rested starting assumption.</p><div class="field"><label for="cell-polarization">Relaxation voltage (V)</label><input id="cell-polarization" type="number" min="-1" max="1" step="any" value="${c.polarization_V}" data-cell-field="polarization_V"></div></details>`}`;}
 else if(w){body=`<div class="terminal-preview">${icon('wire')}<strong>Electrical connection</strong></div><h2>${esc(describeConnection(g,w))}</h2><div class="field"><label for="wire-resistance">Connection resistance</label><div class="input-unit"><input id="wire-resistance" type="number" min="0" max="1000" step="0.1" value="${w.resistance_mohm}" data-wire-field="resistance_mohm" ${S.view==='results'?'disabled':''}><span>mΩ</span></div><p>Resistance makes current harder to pass and creates heat. A worn or poor contact usually has more resistance.</p></div>${S.view!=='results'?`<details><summary>Where this value comes from</summary><div class="field"><label for="wire-source">Source or assumption</label><textarea id="wire-source" data-wire-field="source" rows="3" maxlength="500">${esc(w.source)}</textarea></div></details>`:''}`;}
 else if(terminal){const [cid,pole]=terminal.split(':'),cell=g.cells.find(c=>c.id===cid);body=`<div class="terminal-preview"><span class="terminal-symbol">${pole==='p'?'+':'−'}</span><strong>${esc(cell?.name)} ${pole==='p'?'positive':'negative'}</strong></div><p>Connect this terminal to another cell, or use it as one of the battery’s external outputs.</p><div class="panel-section stack">${btn('connect-from','Connect from here','wire','primary')}${btn('output:positive','Use as positive battery output','plus')}${btn('output:negative','Use as negative battery output',null)}</div>`;}
 return `<aside class="side-panel"><div class="panel-header"><h2>${title}</h2>${iconBtn('close-panel','Close properties','close')}</div><div class="panel-content">${body}<div class="panel-section">${btn('ask-selected','Ask AI about this component','spark','text-button')}</div></div>${S.view!=='results'&& !terminal?`<div class="panel-footer">${btn('delete','Remove '+(c?'cell':'connection'),'trash','quiet danger-button')}</div>`:''}</aside>`;
}
function aiPanel(){const selected=S.graph?.cells.find(c=>c.id===S.selected)?.name|| (S.selected?.startsWith('wire')?'Selected connection':null);return `<aside class="side-panel ai-panel"><div class="panel-header"><div><h2>AI copilot</h2><div class="provider-label"><span class="status-dot"></span>${esc(S.catalog?.copilot.provider||'Local account connection')}</div></div>${iconBtn('close-ai','Close AI copilot','close')}</div><div class="chat-scroll" id="chat-scroll">${!S.messages.length?`<div class="chat-welcome">${icon('spark')}<h2>${S.doc?'Let’s work on your design.':'What would you like to build?'}</h2><p>${S.doc?'Ask about a cell, explore a result or describe a change. You review every proposed edit before applying it.':'Describe your battery, or start with an idea below. I’ll prepare an editable design for you to review.'}</p><div class="suggestions">${(S.doc?['Explain how this battery is connected','What should I test first?','Create a four-cell series alternative']:['Build a four-cell parallel design','Help me choose a first experiment','Explain series and parallel simply']).map(q=>btn('suggest:'+q,esc(q),'arrow')).join('')}</div></div>`:''}${S.messages.map(m=>`<div class="chat-message ${m.role}">${m.role==='assistant'?`<div class="message-source">${icon('spark')}VOLT-FORGE copilot</div>${messageHtml(m.content)}`:esc(m.content)}${m.proposal?proposalHtml(m.proposal):''}</div>`).join('')}${S.chatBusy?'<div class="ai-thinking"><div class="loading-mark"></div>Working with your design…</div>':''}${S.chatError?`<div class="chat-error" role="alert">${esc(S.chatError)}</div>`:''}</div><div class="chat-context">${icon('battery')}${esc(selected||S.graph?.name||'New battery design')}${S.test&&S.view==='results'?' · test results included':''}</div><form id="chat-form" class="chat-form"><div class="chat-compose"><label for="chat-input" class="sr-only">Ask the AI copilot</label><textarea id="chat-input" name="message" placeholder="Ask a question or describe a change…" rows="2" maxlength="4000" ${S.chatBusy?'disabled':''}>${esc(chatDraft)}</textarea><div class="chat-compose-footer"><small>Edits are previewed before applying.</small><button type="submit" class="primary" ${S.chatBusy?'disabled':''} aria-label="Send to AI copilot">${icon('send')}</button></div></div></form></aside>`;}
function messageHtml(content){return esc(content).split(/\n\s*\n/).map(p=>`<p>${p.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\n/g,'<br>')}</p>`).join('');}
function proposalHtml(p){return p.applied?`<div class="proposal applied">${icon('check')} Changes applied</div>`:`<div class="proposal"><h3>Proposed changes</h3><ul>${p.changes.map(c=>`<li>${esc(c)}</li>`).join('')}</ul>${btn('apply:'+p.id,'Apply changes','check','primary')}</div>`;}
function render(){const draft=document.querySelector('#chat-input');if(draft)chatDraft=draft.value;const side=S.ai?aiPanel():S.doc&&S.selected?selectedPanel():'';app.innerHTML=header()+`<div class="studio-layout ${side?'with-panel':''}"><div class="main-region">${!S.doc?home():S.view==='build'?build():S.view==='test'?testSetup():S.view==='whatif'?whatif():S.view==='compare'?comparison():results()}</div>${side}</div>`;bindCanvas();bindChart();if(S.ai){const scroll=document.querySelector('#chat-scroll');scroll.scrollTop=scroll.scrollHeight;}updateSaveStatus();}
function showDialog(title,body){dialog.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2>${iconBtn('close-dialog','Close dialog','close')}</div><div class="dialog-body">${body}</div>`;if(!dialog.open)dialog.showModal();}
function newDialog(){templateChoice='parallel';showDialog('Start a battery design',`<form id="new-form"><div class="field"><label for="new-name">Design name</label><input id="new-name" name="name" value="My battery design" maxlength="100" required></div><div class="field"><label>Choose a starting point</label><div class="template-options">${templateOptions()}</div></div><div class="field"><label for="new-count">Number of cells</label><input id="new-count" name="count" type="number" min="1" max="16" value="4" required></div><div class="dialog-footer">${btn('close-dialog','Cancel',null,'quiet')}<button type="submit" class="primary">Create design ${icon('arrow')}</button></div></form>`);}
function templateOptions(){return [['parallel','parallel','Share the load','Cells side by side, connected in parallel.'],['series','series','Increase the voltage','Cells connected end to end, in series.'],['mixed','grid','Combine both','Pairs in series, with the pairs sharing the load.'],['blank','plus','Start from an empty canvas','Place and connect every cell yourself.']].map(([kind,ico,title,desc])=>`<button type="button" data-act="template:${kind}" class="template-option ${templateChoice===kind?'active':''}">${icon(ico)}<span><strong>${title}</strong><span>${desc}</span></span><span class="chosen"></span></button>`).join('');}
async function refreshCatalog(){const r=await fetch('/api/studio');const j=await r.json();if(j.status!=='ok')throw new Error(j.error?.message);S.catalog=j.result;}
async function openDesign(id){await persist();const doc=await api('open',{design_id:id});loadDoc(doc);dialog.close();render();}
function loadDoc(doc){S.doc=doc;S.graph=clone(doc.graph);S.settings=clone(doc.settings);S.view='build';S.selected=null;S.pending=null;S.tool='select';S.test=null;S.dirty=false;S.history=new History();S.testError=null;S.index=0;S.comparison=null;S.hidden.clear();S.messages=[];S.chatError=null;chatDraft='';}
async function createExample(){await persist();const doc=await api('create',{kind:'parallel',count:4,name:'Four-cell example'});loadDoc(doc);S.onboarding=true;render();await refreshCatalog();}
async function runTest(){
 const form=document.querySelector('#test-form');if(!form?.reportValidity())return;const data=new FormData(form);
 const draft=clone(S.settings),g=clone(S.graph),direction=data.get('direction');
 const intervals=[...form.querySelectorAll('[data-interval]')];
 if(intervals.length>1){let time=0;draft.profile=intervals.map(row=>{const end=time+Number(row.querySelector('.interval-duration').value)*60;const r={start_s:time,end_s:end,current_A:Number(row.querySelector('.interval-current').value)};time=end;return r;});}
 else draft.profile=[{start_s:0,end_s:Number(data.get('duration'))*60,current_A:direction==='rest'?0:Number(data.get('current'))*(direction==='charge'?-1:1)}];
 draft.ambient_C=Number(data.get('ambient'));draft.dt_s=Number(data.get('step'));
 for(const [field,input] of [['temperature_C','limit_temperature'],['current_A','limit_current'],['min_voltage_V','limit_voltage'],['imbalance_pct','limit_imbalance']])draft.limits[field]=data.get(input)===''?null:Number(data.get(input));
 g.thermal.heat_capacity_J_K=Number(data.get('heat_capacity'));g.thermal.ambient_conductance_W_K=Number(data.get('cooling'));
 S.history.push(snapshot());S.settings=draft;S.graph=g;S.dirty=true;S.testError=null;S.running=true;render();
 try{await persist();const test=await api('run',{design_id:S.doc.id,version:S.doc.version});S.doc=await api('open',{design_id:S.doc.id});S.test=test;S.index=test.rows.length-1;S.view='results';S.hidden.clear();await refreshCatalog();}
 catch(e){S.testError=e.message;}
 finally{S.running=false;render();}
}
async function ask(message){
 message=message?.trim();if(!message||S.chatBusy)return;
 S.ai=true;S.chatError=null;chatDraft='';S.messages.push({role:'user',content:message});S.chatBusy=true;render();
 try{await persist();const response=await api('chat',{messages:S.messages.slice(-15).map(m=>({role:m.role,content:m.content})),design_id:S.doc?.id||null,selected:S.selected,test_id:S.view==='results'?S.test?.id||null:null});S.messages.push({role:'assistant',content:response.message,proposal:response.proposal});}
 catch(e){S.chatError=e.message;}
 finally{S.chatBusy=false;render();document.querySelector('#chat-input')?.focus();}
}
async function goView(view){await persist();S.view=view;S.selected=null;S.pending=null;S.testError=null;if(view==='results'&&!S.test&&S.doc.history.length){S.test=await api('test',{test_id:S.doc.history.find(t=>t.current)?.id||S.doc.history[0].id});S.index=S.test.rows.length-1;}render();}
async function comparePage(){await persist();await refreshCatalog();const docs=await Promise.all(S.catalog.designs.filter(d=>d.tests).map(d=>api('open',{design_id:d.id})));S.allTests=docs.flatMap(d=>d.history).sort((a,b)=>b.created_utc.localeCompare(a.created_utc));S.compareLeft=S.comparison?.tests[0].id||(S.allTests.some(t=>t.id===S.compareLeft)?S.compareLeft:S.test?.id)||S.allTests[0]?.id;S.compareRight=S.comparison?.tests[1].id||(S.allTests.some(t=>t.id===S.compareRight)&&S.compareRight!==S.compareLeft?S.compareRight:S.allTests.find(t=>t.id!==S.compareLeft)?.id);S.view='compare';render();}
async function action(action){
 if(action==='home'){await persist();S.doc=null;S.graph=null;S.selected=null;S.test=null;S.ai=false;S.messages=[];S.chatError=null;await refreshCatalog();render();}
 else if(action==='example')await createExample();
 else if(action==='new')newDialog();
 else if(action==='close-dialog')dialog.close();
 else if(action==='designs'){await persist();await refreshCatalog();showDialog('Your battery designs',`<div class="design-list">${S.catalog.designs.map(designRow).join('')}</div><div class="dialog-footer">${btn('new','New design','plus','primary')}</div>`);}
 else if(action.startsWith('open:'))await openDesign(action.slice(5));
 else if(action.startsWith('view:'))await goView(action.slice(5));
 else if(action==='ai'){S.ai=!S.ai;render();if(S.ai)document.querySelector('#chat-input')?.focus();}
 else if(action==='close-ai'){S.ai=false;render();}
 else if(action==='close-panel'){S.selected=null;render();}
 else if(action.startsWith('mode:')){S.mode=action.slice(5);render();}
 else if(action.startsWith('tool:')){S.tool=action.slice(5);S.pending=null;S.selected=null;render();}
 else if(action==='dismiss-guide'){S.onboarding=false;render();}
 else if(action==='help')showDialog('Your first experiment',`<div class="tutorial-step">${icon('pointer')}<div><h3>Build your circuit</h3><p>Add a cell, click it to edit its starting charge, and drag to arrange it. Choose Connect, then click the two terminals you want to join.</p></div></div><div class="tutorial-step">${icon('play')}<div><h3>Choose a test</h3><p>Open Test. Set the current, duration in minutes and room temperature, then run it.</p></div></div><div class="tutorial-step">${icon('chart')}<div><h3>Explore what changed</h3><p>Hover over a graph to inspect values. Click to pin a moment, or use the time slider. Try a what-if to test a single change.</p></div></div><div class="tutorial-step">${icon('spark')}<div><h3>Ask the copilot</h3><p>Ask for an explanation or a different design. The AI shows proposed edits before you apply them.</p></div></div><div class="shortcut-help"><span><kbd class="key">⌘ Z</kbd> Undo</span><span><kbd class="key">Delete</kbd> Remove selection</span><span><kbd class="key">Esc</kbd> Cancel connection</span></div><div class="dialog-footer">${btn('close-dialog','Start exploring','arrow','primary')}</div>`);
 else if(action==='library'){const m=S.catalog.library[S.graph.cells.length%S.catalog.library.length];showDialog('Add a battery cell',`<p>Place a cell on your canvas, then connect its terminals.</p><div class="library-item">${thumbnail({name:'LG M50T cell'})}<div><h3>LG M50T</h3><p>Cylindrical lithium-ion cell</p><p>Measured-data model · about ${fmt(m.capacity_Ah,2)} Ah</p></div>${btn('add:'+m.key,'Add cell','plus','primary',S.graph.cells.length>=16)}</div><details><summary>Choose a different measured sample</summary><p>The library has four separately measured cells of the same type. Use them to explore cell-to-cell variation.</p>${S.catalog.library.map((x,i)=>`<div class="library-item"><div><h3>Measured sample ${i+1}</h3><p>${fmt(x.capacity_Ah,2)} Ah</p></div>${btn('add:'+x.key,'Add','plus','',S.graph.cells.length>=16)}</div>`).join('')}</details>`);}
 else if(action.startsWith('add:')){let id;mutate(()=>{id=addCell(S.graph,action.slice(4));S.selected=id;S.ai=false;});dialog.close();notify('Cell added. Connect its terminals to include it in the circuit.');}
 else if(action==='delete'){if(!S.selected)return;const name=S.graph.cells.find(c=>c.id===S.selected)?.name||'Connection';mutate(()=>{removePart(S.graph,S.selected);S.selected=null;S.pending=null;});notify(name+' removed. Use Undo to restore it.');}
 else if(action==='undo'||action==='redo'){const previous=action==='undo'?S.history.back(snapshot()):S.history.forward(snapshot());if(previous){S.graph=previous.graph;S.settings=previous.settings;S.selected=null;dirty();render();}}
 else if(action==='connect-from'){S.pending=S.selected;S.tool='connect';S.selected=null;render();}
 else if(action.startsWith('output:')){mutate(()=>{S.graph.output[action.slice(7)]=S.selected;});notify('Battery output updated.');}
 else if(action==='rename')showDialog('Name this design',`<form id="rename-form"><label for="rename-input">Design name</label><input id="rename-input" name="name" value="${esc(S.graph.name)}" maxlength="100" required><div class="dialog-footer">${btn('duplicate','Save a copy','copy')}<button type="submit" class="primary">Save name</button></div></form>`);
 else if(action==='duplicate'){await persist();const name=dialog.querySelector('[name=name]')?.value||S.graph.name+' copy';const doc=await api('create',{copy_id:S.doc.id,name});loadDoc(doc);dialog.close();render();notify('A separate copy is ready to edit.');}
 else if(action.startsWith('template:')){templateChoice=action.slice(9);dialog.querySelector('.template-options').innerHTML=templateOptions();const count=dialog.querySelector('#new-count');count.disabled=templateChoice==='blank';count.closest('.field').hidden=templateChoice==='blank';}
 else if(action.startsWith('suggest:'))await ask(action.slice(8));
 else if(action==='ask-selected')await ask('Explain '+(S.graph.cells.find(c=>c.id===S.selected)?.name||'this selected connection')+' and what I can change.');
 else if(action==='ask-results')await ask('Explain the most important finding in this test and suggest one useful design experiment.');
 else if(action.startsWith('apply:')){await persist();const response=await api('apply_proposal',{proposal_id:action.slice(6)});const messages=S.messages;for(const m of messages)if(m.proposal?.id===action.slice(6))m.proposal.applied=true;loadDoc(response);S.messages=messages;S.ai=true;render();notify('Proposed changes applied. Test the new design to see the result.');}
 else if(action.startsWith('metric:')){S.metric=action.slice(7);S.hidden.clear();chartPinned=false;render();}
 else if(action.startsWith('legend:')){const i=Number(action.slice(7));if(S.hidden.has(i))S.hidden.delete(i);else if(S.hidden.size<S.test.graph.cells.length-1)S.hidden.add(i);render();}
 else if(action==='show-assembly'){S.showAssembly=!S.showAssembly;render();if(S.showAssembly)document.querySelector('#results-assembly')?.scrollIntoView({behavior:'smooth',block:'nearest'});}
 else if(action==='edit-selected'){S.view='build';if(!S.graph.cells.some(c=>c.id===S.selected))S.selected=null;render();}
 else if(action==='whatif'){await persist();S.selected=null;S.view='whatif';render();}
 else if(action.startsWith('scenario:')){await persist();S.running=true;render();try{const previous=S.test;const r=await api('investigate',{design_id:S.doc.id,version:S.doc.version,scenario:action.slice(9)});loadDoc(await api('open',{design_id:r.design.id}));S.test=r.test;S.view='results';S.index=r.test.rows.length-1;S.compareLeft=previous?.id;S.compareRight=r.test.id;await refreshCatalog();notify('What-if tested. Your original design is saved separately.');}finally{S.running=false;render();}}
 else if(action==='compare')await comparePage();
 else if(action==='export'&&S.test){const a=document.createElement('a');a.href='/api/studio/export/'+encodeURIComponent(S.test.id);a.download='volt-forge-experiment.zip';a.click();notify('Downloading your report, results and reproducible experiment.');}
 else if(action==='model')modelDialog();
 else if(action==='verification')verificationDialog();
 else if(action==='add-interval'){captureIntervals();const end=S.settings.profile.at(-1).end_s;S.settings.profile.push({start_s:end,end_s:end+60,current_A:0});dirty();render();document.querySelectorAll('#test-form details')[0].open=true;}
 else if(action.startsWith('remove-interval:')){captureIntervals();const i=Number(action.slice(16));if(S.settings.profile.length>1){S.settings.profile.splice(i,1);let t=0;S.settings.profile=S.settings.profile.map(p=>{const dur=p.end_s-p.start_s;const x={...p,start_s:t,end_s:t+dur};t+=dur;return x;});dirty();render();document.querySelectorAll('#test-form details')[0].open=true;}}
 else if(action==='thermal-contacts')thermalContactsDialog();
}
function modelDialog(){showDialog('The model behind your design',`<div class="about-model"><h3>Electrical behaviour</h3><p>Each cell uses a fitted voltage curve, resistance and a relaxation circuit. The solver calculates currents and voltages from your actual connections using Kirchhoff’s laws.</p><h3>Heat and cooling</h3><p>Electrical resistance produces heat. Each cell exchanges heat with the room and through any cell-to-cell thermal contacts you define. Moving a drawing does not invent a physical heat contact.</p><h3>Source data</h3><p>The library uses four measured LG M50T cell profiles from Piombo and colleagues. New cell instances reuse those profiles. The current models run within 22–28 °C; wider temperature operation requires additional calibrated data.</p><p><a href="https://data.mendeley.com/datasets/zh58byr53c/2" target="_blank" rel="noopener">Cell and module experimental campaign</a> · <a href="/measurements" target="_blank" rel="noopener">Explore experimental data</a></p><h3>What a result means</h3><p>This is a numerical estimate for the saved design and settings. Cell fits, connection assumptions and heat-transfer values all affect it. Independent module validation is still required before relying on predictions for real hardware.</p></div>`);}
function verificationDialog(){if(!S.test)return;const v=S.test.summary.verification;showDialog('Calculation checks',`<p>These checks catch solver and accounting mistakes. They do not measure agreement with a real battery.</p><dl><div><dt>Current conservation residual</dt><dd>${v.max_kcl_A.toExponential(2)} A</dd></div><div><dt>Voltage equation residual</dt><dd>${v.max_kvl_V.toExponential(2)} V</dd></div><div><dt>Instantaneous power balance</dt><dd>${v.max_power_residual_W.toExponential(2)} W</dd></div><div><dt>Cell charge accounting</dt><dd>${v.max_cell_charge_residual_As.toExponential(2)} A·s</dd></div><div><dt>Energy integration residual</dt><dd>${v.final_energy_residual_Wh.toExponential(2)} Wh</dd></div><div><dt>Heat accounting residual</dt><dd>${v.max_thermal_residual_J.toExponential(2)} J</dd></div></dl><p class="helper">Time integration has a finite step. Compare progressively smaller steps when studying a new load or topology.</p>`);}
function thermalContactsDialog(){showDialog('Heat transfer between cells',`<p>Add a contact only where your physical design provides a heat path. The value is heat transferred per degree of temperature difference.</p><form id="contacts-form"><div id="contact-rows">${S.graph.thermal.contacts.map((c,i)=>contactRow(c,i)).join('')}</div>${btn('add-contact','Add thermal contact','plus','text-button')}<div class="dialog-footer"><button type="submit" class="primary">Save contacts</button></div></form>`);}
function contactRow(c,i){const opts=selected=>S.graph.cells.map(x=>`<option value="${x.id}" ${x.id===selected?'selected':''}>${esc(x.name)}</option>`).join('');return `<div class="field contact-row"><label>Contact ${i+1}</label><div class="field-row"><select aria-label="First cell">${opts(c.a)}</select><select aria-label="Second cell">${opts(c.b)}</select></div><div class="field-row"><div class="field"><label>Conductance (W/°C)</label><input type="number" min="0" max="100" step="any" value="${c.conductance_W_K}" required></div>${btn('remove-contact:'+i,'Remove','trash','quiet')}</div></div>`;}
function captureIntervals(){const rows=[...document.querySelectorAll('[data-interval]')];if(!rows.length)return;let t=0;S.settings.profile=rows.map(row=>{const d=Number(row.querySelector('.interval-duration').value)*60;const p={start_s:t,end_s:t+d,current_A:Number(row.querySelector('.interval-current').value)};t+=d;return p;});}
function bindCanvas(){
 const svg=document.querySelector('#battery-canvas');if(!svg||S.view!=='build')return;
 svg.addEventListener('pointerdown',e=>{
  const cellEl=e.target.closest('[data-cell]');if(!cellEl||e.target.closest('[data-terminal]')||S.tool==='connect'||e.button!==0)return;
  const id=cellEl.dataset.cell,c=S.graph.cells.find(c=>c.id===id),before=snapshot();
  e.preventDefault();svg.setPointerCapture(e.pointerId);
  const start={x:e.clientX,y:e.clientY,cx:c.x,cy:c.y},scale=svg.viewBox.baseVal.width/svg.getBoundingClientRect().width;let moved=false;
  let frame=0,latest=null;
  const paint=()=>{frame=0;if(!latest||!moved)return;
   c.x=Math.min(2800,Math.max(85,Math.round((start.cx+(latest.x-start.x)*scale)/10)*10));c.y=Math.min(2200,Math.max(130,Math.round((start.cy+(latest.y-start.y)*scale)/10)*10));
   cellEl.setAttribute('transform',`translate(${c.x} ${c.y})`);
   for(const terminal of svg.querySelectorAll(`[data-terminal^="${id}:"]`))terminal.setAttribute('transform',`translate(${c.x-start.cx} ${c.y-start.cy})`);
   for(const w of S.graph.connections){
    const node=svg.querySelector(`[data-wire="${w.id}"]`),geometry=wireGeometry(S.graph,w);
    for(const path of node.querySelectorAll('path'))path.setAttribute('d',geometry.path);
    node.querySelector('g')?.setAttribute('transform',`translate(${geometry.x} ${geometry.y})`);
   }
  };
  const move=event=>{if(Math.hypot(event.clientX-start.x,event.clientY-start.y)>4)moved=true;latest={x:event.clientX,y:event.clientY};if(moved&&!frame)frame=requestAnimationFrame(paint);};
  const up=()=>{if(frame)cancelAnimationFrame(frame);paint();window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',up);window.removeEventListener('pointercancel',up);if(moved){S.history.push(before);S.selected=id;dirty();render();}else{S.selected=id;S.ai=false;S.onboarding=false;render();}};
  window.addEventListener('pointermove',move);window.addEventListener('pointerup',up,{once:true});window.addEventListener('pointercancel',up,{once:true});
 });
}
function bindChart(){const svg=document.querySelector('#result-chart');if(!svg||!S.test)return;let frame=0;
 const at=event=>{const rect=svg.getBoundingClientRect(),x=(event.clientX-rect.left)*Number(svg.dataset.total)/rect.width;const time=Math.max(0,Math.min(1,(x-Number(svg.dataset.left))/Number(svg.dataset.width)))*Number(svg.dataset.duration);return nearestIndex(S.test.rows,time);};
 svg.addEventListener('pointermove',e=>{if(chartPinned)return;const index=at(e),x=e.clientX;if(frame)cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{frame=0;if(svg.isConnected&&!chartPinned)probe(index,x);});});
 svg.addEventListener('pointerleave',()=>{if(frame)cancelAnimationFrame(frame);frame=0;if(!chartPinned)document.querySelector('#chart-tooltip')?.classList.remove('visible');});
 svg.addEventListener('click',e=>{S.index=at(e);chartPinned=!chartPinned;probe(S.index,e.clientX);});
}
function probe(index,clientX){S.index=Math.max(0,Math.min(S.test.rows.length-1,index));const svg=document.querySelector('#result-chart');if(!svg)return;svg.querySelector('#chart-probe').innerHTML=probeSvg(S.test,S.metric,S.index,S.hidden,Number(svg.dataset.min),Number(svg.dataset.max),Number(svg.dataset.duration));
 const tooltip=document.querySelector('#chart-tooltip');tooltip.innerHTML=pointValues(S.test,S.metric,S.index,S.hidden);if(clientX!==undefined){tooltip.classList.add('visible');const rect=document.querySelector('#chart-area').getBoundingClientRect();tooltip.style.left=Math.max(8,Math.min(rect.width-tooltip.offsetWidth-8,clientX-rect.left+18))+'px';}
 const slider=document.querySelector('#result-time');if(slider){slider.value=S.index;slider.setAttribute('aria-valuetext',timeLabel(S.test.rows[S.index].time_s));}const readout=document.querySelector('#time-readout');if(readout)readout.textContent=timeLabel(S.test.rows[S.index].time_s);
 const assembly=document.querySelector('#results-assembly');if(assembly)assembly.innerHTML=renderCanvas(S.test.graph,{mode:S.mode,selected:S.selected,layer:S.metric,row:S.test.rows[S.index],prefix:'results'});
 if(S.selected&&!S.ai){const panel=document.querySelector('.side-panel');if(panel)panel.outerHTML=selectedPanel();}
}
app.addEventListener('click',async event=>{const button=event.target.closest('[data-act]');if(button){try{await action(button.dataset.act);}catch(e){notify(e.message,true);}return;}
 const term=event.target.closest('[data-terminal]');if(term&&S.doc){if(S.view!=='build')return;const t=term.dataset.terminal;if(S.tool==='connect'){if(!S.pending){S.pending=t;render();}else{try{mutate(()=>{connect(S.graph,S.pending,t);S.pending=null;S.selected=null;});}catch(e){notify(e.message,true);}}}else{S.selected=t;S.ai=false;render();}return;}
 const wire=event.target.closest('[data-wire]');if(wire&&S.doc){S.selected=wire.dataset.wire;S.ai=false;render();return;}
 const cell=event.target.closest('[data-cell]');if(cell&&S.view==='results'){S.selected=cell.dataset.cell;S.ai=false;render();}
});
dialog.addEventListener('click',async event=>{const b=event.target.closest('[data-act]');if(!b)return;try{if(b.dataset.act==='add-contact'){const holder=dialog.querySelector('#contact-rows');holder.insertAdjacentHTML('beforeend',contactRow({a:S.graph.cells[0]?.id,b:S.graph.cells[1]?.id,conductance_W_K:.05},holder.children.length));}else if(b.dataset.act.startsWith('remove-contact:'))b.closest('.contact-row').remove();else await action(b.dataset.act);}catch(e){notify(e.message,true);}});
app.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;try{if(form.id==='home-chat')await ask(new FormData(form).get('prompt'));else if(form.id==='chat-form')await ask(new FormData(form).get('message'));else if(form.id==='test-form')await runTest();else if(form.id==='compare-form'){const data=new FormData(form);S.compareLeft=data.get('left');S.compareRight=data.get('right');S.comparison=await api('compare',{test_ids:[S.compareLeft,S.compareRight]});render();}}catch(e){notify(e.message,true);}});
dialog.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;try{if(form.id==='new-form'){await persist();const data=new FormData(form);const doc=await api('create',{kind:templateChoice,count:templateChoice==='blank'?0:Number(data.get('count')),name:data.get('name')});loadDoc(doc);dialog.close();render();await refreshCatalog();}else if(form.id==='rename-form'){const name=new FormData(form).get('name').trim();if(!name)return;mutate(()=>S.graph.name=name);await persist();dialog.close();render();}else if(form.id==='contacts-form'){const contacts=[...form.querySelectorAll('.contact-row')].map(row=>{const selects=row.querySelectorAll('select');return {a:selects[0].value,b:selects[1].value,conductance_W_K:Number(row.querySelector('input').value)};});mutate(()=>S.graph.thermal.contacts=contacts);await persist();dialog.close();render();}}catch(e){notify(e.message,true);}});
app.addEventListener('input',event=>{if(event.target.id==='result-time')probe(Number(event.target.value));if(event.target.id==='cell-charge-range'){const input=document.querySelector('#cell-charge');if(input)input.value=event.target.value;}if(event.target.id==='chat-input')chatDraft=event.target.value;});
app.addEventListener('change',async event=>{const el=event.target;try{if(el.dataset.cellField){if(!el.reportValidity())return;const cell=S.graph.cells.find(c=>c.id===S.selected),field=el.dataset.cellField;if(!cell)return;mutate(()=>cell[field]=['name','model'].includes(field)?el.value:Number(el.value));}
 else if(el.dataset.cellThermal){if(!el.reportValidity())return;mutate(()=>{const th=S.graph.thermal;th.cell_parameters??={};th.cell_parameters[S.selected]??={};th.cell_parameters[S.selected][el.dataset.cellThermal]=Number(el.value);});}
 else if(el.id==='cell-charge-range'){const cell=S.graph.cells.find(c=>c.id===S.selected);mutate(()=>cell.charge_pct=Number(el.value));}
 else if(el.dataset.wireField){if(!el.reportValidity())return;const wire=S.graph.connections.find(w=>w.id===S.selected);mutate(()=>wire[el.dataset.wireField]=el.dataset.wireField==='source'?el.value:Number(el.value));}
 else if(el.closest('#test-form')&&el.matches('input,select')){
  if(!el.reportValidity())return;
  if(el.matches('.interval-current,.interval-duration')){
   captureIntervals();const current=document.querySelector('#test-current'),direction=document.querySelector('#test-direction');
   document.querySelector('#test-duration').value=S.settings.profile.at(-1).end_s/60;
   if(S.settings.profile.length===1){current.value=Math.abs(S.settings.profile[0].current_A);direction.value=S.settings.profile[0].current_A<0?'charge':S.settings.profile[0].current_A===0?'rest':'discharge';}
  }else if(['test-current','test-duration','test-direction'].includes(el.id)&&S.settings.profile.length===1){
   const form=document.querySelector('#test-form'),data=new FormData(form),direction=data.get('direction');
   const current=direction==='rest'?0:Number(data.get('current'))*(direction==='charge'?-1:1);
   S.settings.profile=[{start_s:0,end_s:Number(data.get('duration'))*60,current_A:current}];
   form.querySelector('.interval-current').value=current;form.querySelector('.interval-duration').value=Number(data.get('duration'));
  }else if(el.id==='test-ambient')S.settings.ambient_C=Number(el.value);
  else if(el.id==='test-step')S.settings.dt_s=Number(el.value);
  else if(el.id==='heat-capacity'){S.graph.thermal.heat_capacity_J_K=Number(el.value);for(const p of Object.values(S.graph.thermal.cell_parameters||{}))delete p.heat_capacity_J_K;}
  else if(el.id==='cooling-conductance'){S.graph.thermal.ambient_conductance_W_K=Number(el.value);for(const p of Object.values(S.graph.thermal.cell_parameters||{}))delete p.ambient_conductance_W_K;}
  else{const target={'target-temperature':'temperature_C','target-current':'current_A','target-voltage':'min_voltage_V','target-imbalance':'imbalance_pct'}[el.id];if(target)S.settings.limits[target]=el.value===''?null:Number(el.value);}
  dirty();
 }
 else if(el.id==='test-history'&&el.value){S.test=await api('test',{test_id:el.value});S.index=S.test.rows.length-1;S.view='results';S.selected=null;S.hidden.clear();render();}
 }catch(e){notify(e.message,true);}});
app.addEventListener('keydown',event=>{const target=event.target;if(target.matches('[data-cell],[data-terminal],[data-wire]')&&['Enter',' '].includes(event.key)){event.preventDefault();if(target.dataset.cell){S.selected=target.dataset.cell;S.ai=false;render();}else target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(target.id==='chat-input'&&event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();ask(target.value);}});
window.addEventListener('keydown',event=>{if(dialog.open||event.target.matches('input,textarea,select,[contenteditable]'))return;if(event.key==='Escape'){S.pending=null;S.tool='select';S.selected=null;render();}if(S.doc&&S.view==='build'){if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='z'){event.preventDefault();action(event.shiftKey?'redo':'undo');}if(['Delete','Backspace'].includes(event.key)&&S.selected&&!S.selected.includes(':')){event.preventDefault();action('delete');}}});
window.addEventListener('beforeunload',e=>{if(S.dirty||S.saving){e.preventDefault();e.returnValue='';}});
(async()=>{try{const [session]=await Promise.all([fetch('/api/session').then(r=>r.json()),refreshCatalog()]);S.token=session.result.token;render();}catch(e){app.innerHTML=`<main class="empty-error"><h1>The workspace could not open</h1><p>${esc(e.message)}</p>${btn('reload','Try again','arrow','primary')}</main>`;app.querySelector('[data-act=reload]').onclick=()=>location.reload();}})();
